import test from 'node:test';
import assert from 'node:assert/strict';
import { batches } from '../src/batches.js';

// Literal expectations follow from the minimum number of batches needed.
const validCases = [
  [0, 1, 0],
  [0, 7, 0],
  [1, 1, 1],
  [7, 1, 7],
  [1, 7, 1],
  [6, 7, 1],
  [7, 7, 1],
  [8, 7, 2],
  [14, 7, 2],
  [15, 7, 3],
];

for (const [total, size, expected] of validCases) {
  test(`batches(${total}, ${size}) returns ${expected}`, () => {
    assert.equal(batches(total, size), expected);
  });
}

const invalidTotals = [-1, -7, -0.5, 0.5, 7.5, NaN, Infinity, -Infinity];
for (const total of invalidTotals) {
  test(`rejects invalid total ${String(total)} with a valid size`, () => {
    assert.throws(() => batches(total, 7), RangeError);
  });
}

const invalidSizes = [0, -1, -7, -0.5, 0.5, 7.5, NaN, Infinity, -Infinity];
for (const size of invalidSizes) {
  test(`rejects invalid size ${String(size)} with a positive total`, () => {
    assert.throws(() => batches(7, size), RangeError);
  });

  test(`rejects invalid size ${String(size)} with zero total`, () => {
    assert.throws(() => batches(0, size), RangeError);
  });
}

